import OpenAI from 'openai';
import { z } from 'zod';

import { loadShipmentExplainerInstruction } from './instructions.js';
import { ShipmentSnapshotSchema } from './types.js';

const ModelIdentifierSchema = z.string().trim().min(1);

/**
 * Requests a staff-reviewable shipment explanation from a validated snapshot.
 * @param model The caller-selected OpenAI model identifier.
 * @param snapshot The caller-supplied tracking snapshot.
 * @returns The model's draft text, without sending it to a customer.
 */
export const draftShipmentExplanation = async (
  model: string,
  snapshot: unknown,
): Promise<string> => {
  const validatedModel = ModelIdentifierSchema.parse(model);
  const validatedSnapshot = ShipmentSnapshotSchema.parse(snapshot);
  const client = new OpenAI();

  const response = await client.responses.create({
    model: validatedModel,
    instructions: await loadShipmentExplainerInstruction(),
    input: JSON.stringify(validatedSnapshot),
    store: false,
  });

  return response.output_text;
};

import { readFile } from 'node:fs/promises';

/**
 * Loads the canonical shipment-explainer instruction from the source tree.
 * @returns The instruction text for a Responses request.
 */
export const loadShipmentExplainerInstruction = async (): Promise<string> =>
  readFile(new URL('../../moldea/agents/shipment-explainer/instruction.md', import.meta.url), 'utf8');

import { z } from 'zod';

// carrier scans may provide a date without a time
const CarrierScanOccurrenceSchema = z.union([z.iso.date(), z.iso.datetime({ offset: true })]);

// the closed snapshot contract keeps unrelated customer data out of model input
export const ShipmentSnapshotSchema = z.strictObject({
  reference: z.string().trim().min(1).max(64),
  carrier: z.string().trim().min(1).max(128),
  snapshotTakenAt: z.iso.datetime({ offset: true }),
  estimatedDeliveryDate: z.iso.date().nullable(),
  scans: z
    .array(
      z.strictObject({
        occurredAt: CarrierScanOccurrenceSchema,
        description: z.string().trim().min(1).max(256),
      }),
    )
    .max(64),
  unknowns: z.array(z.string().trim().min(1).max(256)).max(16),
});

export type IShipmentSnapshot = z.infer<typeof ShipmentSnapshotSchema>;
